  trailX += (input.mouse.x - trailX) * P.mouseTrailSmoothing;
  trailY += (input.mouse.y - trailY) * P.mouseTrailSmoothing;

  uniforms.set('mousePos', [input.mouse.x, input.mouse.y]);
  uniforms.set('mouseTrailPos', [trailX, trailY]);

